// ==UserScript==
// @name         ART • Chat Saya | Suara Otomatis • Hitung Chat Aktif
// @namespace    local.chatgacor.chatsaya.alert
// @version      11.0.0
// @description  3 suara asli. Hanya hitung chat yang masih ada di Chat Saya; hilang=hapus alarm, kosong=diam. Baca/balas=berhenti. Queue >15. Bubble bulan mini.
// @author       ART
// @match        https://app.chatgacor.com/app/*/my-chats*
// @grant        none
// @run-at       document-idle
// @noframes
// ==/UserScript==

(() => {
  'use strict';
  if (window.top !== window.self || window.__ART_CHATGACOR_ALERT_11__) return;
  window.__ART_CHATGACOR_ALERT_11__ = true;
  // Suara pesan masuk dari Suara_ART (1).wav: satu ucapan Incoming chat.
  // Berkas suara sudah tertanam: tidak perlu impor, rekam, atau ambil dari LiveChat.
  const VOICE = 'data:audio/mpeg;base64,';
  // Chime asli dari Suara_ART (2).wav (hening depan dipotong).
  const REMINDER_AUDIO = 'data:audio/mpeg;base64,';
  // Ucapan asli dari Suara_ART (3).wav: 'New visitor in the queue'.
  const QUEUE_AUDIO = 'data:audio/mpeg;base64,';
  function getSavedAudio(type='incoming') {
    return type==='incoming'||type==='messages' ? VOICE : '';
  }
  if (location.hostname !== 'app.chatgacor.com') return;
  function bootChatGacor() {
  const MATCH = /^\/app\/([^/]+)\/my-chats(?:\/([^/?#]+))?\/?$/i;
  const ROUTE = location.pathname.match(MATCH);
  if (!ROUTE) return;
  const APP_ID = ROUTE[1];
  const DB_KEY = `art_chatgacor_chatsaya_v9_${APP_ID}`; // pertahankan preferensi suara dan posisi versi lama
  const REMINDER_REPEAT_SECONDS = 8; // interval suara rekaman kedua selama masih ada chat belum dibaca
  const MAX_HISTORY = 280;
  const TIME = () => Date.now();
  const normalize = s => String(s || '').replace(/\s+/g, ' ').trim();
  const normKey = s => normalize(s).toLocaleLowerCase('id-ID');
  const hash = input => {
    let n = 2166136261;
    for (let i = 0; i < input.length; i++) n = Math.imul(n ^ input.charCodeAt(i), 16777619);
    return (n >>> 0).toString(36);
  };

  const storage = (() => {
    try { return JSON.parse(localStorage.getItem(DB_KEY) || '{}'); } catch { return {}; }
  })();
  const state = {
    enabled: typeof storage.enabled === 'boolean' ? storage.enabled : false,
    compact: !!storage.compact,
    items: storage.items && typeof storage.items === 'object' ? storage.items : {},
    firstScan: !!storage.firstScan,
    firstScanV5: !!storage.firstScanV5,
    queueCount: Number.isFinite(storage.queueCount) ? storage.queueCount : null,
    queueThresholdNotified: !!storage.queueThresholdNotified,
    extras: storage.extras && typeof storage.extras==='object' ? storage.extras : {},
    pos: storage.pos || null
  };
  let ready = false;
  let ac = null;
  let reminderLoop = null;
  let reminderLoading = null;
  let reminderDecoded = null;
  let reminderDecoding = null;
  let reminderEpoch = 0;
  let queueBuffer = null;
  let queueDecodeTask = null;
  let queueAlertInFlight = false;
  let lastQueueAlertAt = 0;
  let queueCountNow = 0;
  let queueCountSource = 'daftar';
  let queuePendingWhileLocked = false;
  let queueSource = null;
  const activeIncomingSources = new Set();
  // Riwayat lama jangan pernah dianggap chat aktif sebelum daftar Chat Saya diperiksa.
  let listScanned = false;
  let baselineEstablished = false;
  let emptyScans = 0;
  const QUEUE_LIMIT = 15;
  let scanTimer = null;
  let scanRows = 0;
  let lastScan = 0;
  let toastTimer = null;
  let latestList = [];
  let lastPersist = 0;
  let decodedAudio = new Map(), pendingDecode = new Map();
  function preloadOriginalSound(type='incoming') {
    const data=getSavedAudio(type);
    if(!data || !ready || !ac || ac.state!=='running')return Promise.resolve(false);
    const prev=decodedAudio.get(type);
    if(prev && prev.data===data)return Promise.resolve(true);
    if(pendingDecode.has(type))return pendingDecode.get(type);
    const task=(async()=>{
      try {
        const raw=atob(data.slice(data.indexOf(',')+1));
        const bytes=new Uint8Array(raw.length);
        for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);
        const decoded=await ac.decodeAudioData(bytes.buffer);
        decodedAudio.set(type,{data,buffer:decoded});
        return true;
      }catch(e){console.warn('[ART] Gagal decode audio '+type,e);return false;}
      finally{pendingDecode.delete(type);}
    })();
    pendingDecode.set(type,task);
    return task;
  }
  function fallbackTone(type='incoming') {
    if(!ready || !ac || ac.state!=='running')return;
    const sounds={
      messages:[[0,910],[.15,1110]],
      incoming:[[0,690],[.18,860],[.36,1080]],
      tickets:[[0,760],[.16,760],[.33,1180]],
      queue:[[0,1010],[.19,820],[.39,1010]]
    };
    const t0=ac.currentTime+.02;
    for(const [dt,f] of (sounds[type]||sounds.incoming)) {
      const osc=ac.createOscillator(),g=ac.createGain();
      osc.type='sine';osc.frequency.setValueAtTime(f,t0+dt);
      g.gain.setValueAtTime(.0001,t0+dt);
      g.gain.exponentialRampToValueAtTime(.15,t0+dt+.026);
      g.gain.exponentialRampToValueAtTime(.0001,t0+dt+.18);
      osc.connect(g);g.connect(ac.destination);osc.start(t0+dt);osc.stop(t0+dt+.2);
    }
  }
  async function playIncomingTone(type='incoming') {
    if(!state.enabled || !ready || !ac || ac.state!=='running')return;
    await preloadOriginalSound(type);
    if(!state.enabled || !ready || !ac || ac.state!=='running')return;
    // Jangan lanjutkan suara async apabila chat sudah hilang ketika audio selesai diproses.
    if (!listScanned || scanRows===0 || !goodRoute()) return;
    const entry=decodedAudio.get(type);
    if(entry && entry.data===getSavedAudio(type)) {
      const src=ac.createBufferSource();src.buffer=entry.buffer;src.connect(ac.destination);
      activeIncomingSources.add(src);
      src.onended=()=>{activeIncomingSources.delete(src);try{src.disconnect();}catch{}};
      src.start();
    } else fallbackTone(type);
  }
  function persist(force = false) {
    if (!force && TIME() - lastPersist < 1250) return;
    lastPersist = TIME();
    const entries = Object.entries(state.items);
    if (entries.length > MAX_HISTORY) {
      entries.sort((a,b) => (b[1].time || 0) - (a[1].time || 0));
      state.items = Object.fromEntries(entries.slice(0, MAX_HISTORY));
    }
    try {
      localStorage.setItem(DB_KEY, JSON.stringify({
        enabled: state.enabled, compact: state.compact,
        queueCount: state.queueCount, queueThresholdNotified: state.queueThresholdNotified,
        items: state.items, firstScan: state.firstScan, firstScanV5: state.firstScanV5, extras: state.extras, pos: state.pos
      }));
    } catch (err) { console.warn('[ART ChatGacor] Penyimpanan tidak tersedia', err); }
  }

  // Bubble bulan sabit, kecil dan bisa diseret. Seluruh CSS di Shadow DOM.
  const host = document.createElement('div');
  host.id = 'art-chatgacor-alert-root';
  host.style.cssText = 'position:fixed;right:14px;bottom:14px;z-index:2147483646;pointer-events:auto';
  (document.documentElement || document.body).appendChild(host);
  const ui = host.attachShadow({mode:'open'});
  ui.innerHTML = `
    <style>
      :host{all:initial}*{box-sizing:border-box}
      .wrap{width:182px;overflow:hidden;border-radius:19px;color:#f8eeff;
        background:linear-gradient(157deg,#462550 0%,#261b48 46%,#161b38 100%);
        border:1px solid #c4a6fa77;box-shadow:0 14px 38px #1008209e,0 0 18px #e78fd527,inset 0 1px 0 #ffffff26;
        font:11px/1.4 system-ui,Segoe UI,Arial,sans-serif;backdrop-filter:blur(12px)}
      header{display:flex;gap:7px;align-items:center;padding:9px 8px;cursor:move;user-select:none;touch-action:none;
        background:linear-gradient(90deg,#f0a8d321,#9185e522)}
      .orb{position:relative;display:grid;place-items:center;flex-shrink:0;width:29px;height:29px;border-radius:50%;
        background:radial-gradient(circle at 30% 25%,#fff3bd,#f6bdff 58%,#9076e6);box-shadow:0 0 14px #eaa8fa85}
      .moon{position:absolute;left:5px;top:4px;width:18px;height:18px;border-radius:100%;background:#fff4cc;
        box-shadow:4px -4px 0 1px #6d4a9c,0 0 9px #fff2d0a8;transform:rotate(-18deg)}
      .identity{min-width:0;flex:1}.identity strong{display:block;font-size:11px;white-space:nowrap}
      .identity small{display:block;color:#e0c3ed;font-size:9px;margin-top:1px}
      .min{border:1px solid #ffffff22;background:#ffffff16;color:#fff;border-radius:8px;width:21px;height:21px;
        cursor:pointer;font-size:14px;font-weight:600;line-height:18px;padding:0}
      main{padding:0 8px 8px}.info{display:flex;align-items:center;gap:5px;padding:6px;margin:0 0 7px;
        border-radius:10px;border:1px solid #ffffff1c;background:#ffffff12}
      .led{width:7px;height:7px;flex:none;border-radius:50%;background:#ffc777;box-shadow:0 0 6px #ffcc77}
      .led.on{background:#6dfac9;box-shadow:0 0 6px #6dfac9}.led.off{background:#ff6c9d;box-shadow:0 0 6px #ff6c9d}
      .status{flex:1;min-width:0;color:#e1ceff;font-size:9.3px}.status strong{display:block;color:#fff;font-size:10.4px}
      .num{background:#e5a9ff28;color:#f8daff;border:1px solid #e7b6ff5c;border-radius:7px;padding:3px 5px;font-weight:750;font-size:13px;min-width:24px;text-align:center}
      .queue{display:flex;align-items:center;gap:5px;margin-bottom:7px;padding:5px 6px;border-radius:9px;background:#1f1944b0;border:1px solid #ffffff18}
      .queue strong{font-size:11px;color:#fbe7ff;margin-left:auto}.queue em{font-style:normal;font-size:9px;color:#d8b8eb}
      .queue.high{border-color:#f9cf89aa;background:#9250355c}.queue.high strong,.queue.high em{color:#ffe4a4}
      .buttons{display:flex;gap:5px}.buttons button{flex:1;min-width:0;border-radius:9px;cursor:pointer;font-size:10px;font-weight:700;padding:7px 3px}
      .primary{border:0;background:linear-gradient(110deg,#ffd5aa,#f6a5eb);color:#422247}
      .secondary{flex:0 0 39px!important;border:1px solid #e3b6ff6b;background:#8960a555;color:#fce8ff}
      .foot{margin-top:5px;display:flex;justify-content:space-between;gap:5px}
      .foot button{font:9px/1.4 system-ui;cursor:pointer;border:0;background:transparent;color:#f2c9f1;padding:4px 0}
      .audio-status,.meta{font-size:8.6px;color:#cdb1df;line-height:1.35;margin-top:6px}
      .meta{display:flex;justify-content:space-between;gap:5px}
      #toast{display:none;border:1px solid #f1baff66;border-radius:8px;padding:6px;margin-top:5px;background:#71366a;color:#ffefff;font-size:9px}
      .wrap.compact{width:131px;border-radius:17px}.compact header{padding:6px}.compact main,.compact .identity small{display:none}
      .compact .orb{width:25px;height:25px}.compact .moon{transform:scale(.79) rotate(-18deg);left:3px;top:3px}
      .wrap.alert .orb{animation:pulse 1.7s ease-in-out infinite}@keyframes pulse{50%{box-shadow:0 0 20px #ffe2a8,0 0 0 4px #e6b4ff2d}}
    </style>
    <section class="wrap" id="wrap">
      <header id="drag"><span class="orb"><span class="moon"></span></span>
        <span class="identity"><strong>ART • Chat Saya</strong><small>3 suara asli · mini</small></span>
        <button type="button" class="min" id="min" title="Perkecil / perbesar">−</button></header>
      <main>
        <div class="info"><i class="led" id="led"></i><div class="status"><strong id="status">Memeriksa chat</strong><span id="detail">Khusus Chat Saya</span></div><div class="num" id="count">0</div></div>
        <div class="queue" id="queueBox"><span>☾</span><em>Jumlah Chat Saya</em><strong id="queueCount">—</strong></div>
        <div class="buttons"><button type="button" class="primary" id="enable">Aktifkan suara</button><button type="button" class="secondary" id="test" title="Uji ketiga suara">Tes</button></div>
        <div class="audio-status" id="audioStatus">Suara: chat masuk · belum dibaca · antrean >15</div>
        <div class="meta"><span id="rows">Memeriksa...</span><span id="countdown">Siaga</span></div>
        <div id="toast" aria-live="polite"></div>
        <div class="foot"><button id="done" type="button">✓ Sudah baca</button><button id="all" type="button">Hapus alarm</button></div>
      </main>
    </section>`;
  const $ = id => ui.getElementById(id);
  const wrap = $('wrap');
  const toast = txt => {
    const el = $('toast'); el.textContent = txt; el.style.display = 'block';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => { el.style.display='none'; }, 4100);
  };
  const visible = el => !!el && !!el.getClientRects().length && getComputedStyle(el).visibility !== 'hidden';
  const currentChatId = () => (location.pathname.match(MATCH) || [,'',''])[2] || '';

  // Aktifkan AudioContext hanya dari klik pengguna. Chrome biasanya menolak autoplay sebelum interaksi.
  async function unlockAudio() {
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return false;
      if (!ac || ac.state === 'closed') ac = new Ctx();
      if (ac.state !== 'running') await ac.resume();
      ready = ac.state === 'running';
      if (ready) { preloadOriginalSound('incoming'); decodeQueueSound(); flushQueueAudio(); }
      render();
      return ready;
    } catch (e) {
      console.debug('[ART ChatGacor] Audio belum diizinkan', e);
      return false;
    }
  }

  // Memakai audio chime dari WAV yang pengguna berikan, bukan bunyi sintetis 30 detik.
  async function decodeReminder() {
    if (!ready || !ac || ac.state !== 'running') return null;
    if (reminderDecoded) return reminderDecoded;
    if (reminderDecoding) return reminderDecoding;
    reminderDecoding = (async () => {
      try {
        const raw = atob(REMINDER_AUDIO.slice(REMINDER_AUDIO.indexOf(',') + 1));
        const bytes = new Uint8Array(raw.length);
        for (let i=0; i<raw.length; i++) bytes[i] = raw.charCodeAt(i);
        reminderDecoded = await ac.decodeAudioData(bytes.buffer);
        return reminderDecoded;
      } catch(e) {
        console.warn('[ART ChatGacor] Audio pengingat tidak bisa dibaca:', e);
        return null;
      } finally { reminderDecoding = null; }
    })();
    return reminderDecoding;
  }
  function activeReminder() {
    return goodRoute() && listScanned && scanRows > 0 && pendingCount() > 0 && state.enabled && ready && ac && ac.state === 'running';
  }
  function stopReminderLoop() {
    reminderEpoch++;
    if (reminderLoop) {
      try { reminderLoop.stop(); reminderLoop.disconnect(); } catch {}
      reminderLoop = null;
    }
  }
  // Web Audio loop tetap terjadwal walaupun tab di belakang layar.
  function syncReminderLoop() {
    if (!activeReminder()) {
      if (reminderLoop || reminderLoading) stopReminderLoop();
      return;
    }
    if (reminderLoop || reminderLoading) return;
    const epoch = reminderEpoch;
    reminderLoading = decodeReminder().then(sound => {
      if (!sound || reminderEpoch !== epoch || !activeReminder()) return;
      const frames = Math.max(sound.length + 1, Math.ceil(ac.sampleRate * REMINDER_REPEAT_SECONDS));
      const padded = ac.createBuffer(sound.numberOfChannels, frames, ac.sampleRate);
      for (let ch = 0; ch < sound.numberOfChannels; ch++) {
        padded.getChannelData(ch).set(sound.getChannelData(ch));
      }
      const source = ac.createBufferSource();
      source.buffer = padded;
      source.loop = true;
      source.connect(ac.destination);
      reminderLoop = source;
      // Biarkan suara Incoming chat diputar terlebih dahulu.
      source.start(ac.currentTime + 2.0);
    }).catch(e => console.warn('[ART ChatGacor] Pengingat gagal:', e))
      .finally(() => { reminderLoading = null; });
  }
  async function testReminder() {
    const sound = await decodeReminder();
    if (!sound || !ac || ac.state !== 'running') return;
    const src = ac.createBufferSource(); src.buffer = sound;
    src.connect(ac.destination); src.start();
  }
  async function decodeQueueSound() {
    if (!ready || !ac || ac.state !== 'running') return null;
    if (queueBuffer) return queueBuffer;
    if (queueDecodeTask) return queueDecodeTask;
    queueDecodeTask = (async () => {
      try {
        const raw = atob(QUEUE_AUDIO.slice(QUEUE_AUDIO.indexOf(',')+1));
        const bytes = new Uint8Array(raw.length);
        for(let i=0;i<raw.length;i++) bytes[i] = raw.charCodeAt(i);
        queueBuffer = await ac.decodeAudioData(bytes.buffer);
        return queueBuffer;
      } catch(e) { console.warn('[ART] Audio queue gagal dibaca',e); return null; }
      finally { queueDecodeTask = null; }
    })();
    return queueDecodeTask;
  }
  function stopChatSounds() {
    // Suara tidak boleh tertinggal dari chat yang sudah keluar dari Chat Saya.
    stopReminderLoop();
    for(const src of activeIncomingSources) {try{src.stop();src.disconnect();}catch{}}
    activeIncomingSources.clear();
    if(queueSource) {try{queueSource.stop();queueSource.disconnect();}catch{} queueSource=null;}
    queueAlertInFlight=false;
  }
  async function playQueueSound(force=false) {
    if (!ready || !state.enabled || !ac || ac.state !== 'running') return;
    if (!force && (!listScanned || scanRows===0 || queueCountNow<=QUEUE_LIMIT)) return;
    if (!force && (queueAlertInFlight || TIME()-lastQueueAlertAt<4000)) return;
    const now=TIME();lastQueueAlertAt=now;queueAlertInFlight=true;
    try {
      const b=await decodeQueueSound();
      if (!ready || !state.enabled || !b || (!force && (scanRows===0 || queueCountNow<=QUEUE_LIMIT))) {
        queueAlertInFlight=false;return;
      }
      const src=ac.createBufferSource();src.buffer=b;src.connect(ac.destination);
      if(queueSource) {try{queueSource.stop();queueSource.disconnect();}catch{}}
      queueSource=src;
      src.onended=()=>{if(queueSource===src)queueSource=null;queueAlertInFlight=false;try{src.disconnect();}catch{}};
      src.start();
      if(!force)toast('Chat Saya lebih dari 15 • suara antrean.');
    } catch(e) { queueAlertInFlight=false;console.warn(e); }
  }
  // Lebih dari 15 = 16 atau lebih. Tidak berbunyi berulang saat jumlah diam.
  // Setiap kenaikan jumlah chat di atas batas = 1 notifikasi queue.
  function updateQueueCount(count) {
    if (!Number.isFinite(count) || count < 0) return;
    queueCountNow = count;
    if (count <= QUEUE_LIMIT && queueSource) {
      try {queueSource.stop();queueSource.disconnect();}catch{}
      queueSource=null;queueAlertInFlight=false;
    }
    const last=state.queueCount;
    let fire=false;
    if(last === null) {
      // Saat awal, jika sudah 16+, beri tahu satu kali setelah audio aktif.
      fire = count > QUEUE_LIMIT && !state.queueThresholdNotified;
    } else if(count <= QUEUE_LIMIT) {
      state.queueThresholdNotified=false;
    } else if(count > last) {
      fire=true;
    } else if(!state.queueThresholdNotified) {
      fire=true;
    }
    state.queueCount=count;
    if(count>QUEUE_LIMIT && fire) {
      state.queueThresholdNotified=true;
      if(state.enabled && ready) { playQueueSound(); queuePendingWhileLocked=false; }
      else queuePendingWhileLocked=true;
    }
    if(count<=QUEUE_LIMIT) queuePendingWhileLocked=false;
    if(count!==last || fire) persist(true);
  }
  function flushQueueAudio() {
    if(queuePendingWhileLocked && state.queueCount>QUEUE_LIMIT && ready && state.enabled) {
      queuePendingWhileLocked=false;playQueueSound();
    }
  }
  // Ambil jumlah resmi pada label Chat Saya apabila ditampilkan, bukan angka 'Semua chat'.
  function nativeMyChatsCount() {
    // Hanya label yang secara jelas menunjukkan angka setelah tulisan "Chat Saya".
    // Jangan baca angka dari preview pesan maupun menu Semua Chat.
    const options=Array.from(document.querySelectorAll('a,button,[role="tab"],[role="button"]'));
    for(const el of options.slice(0,350)) {
      if(!visible(el) || el.closest('#art-chatgacor-alert-root'))continue;
      const full=normalize(el.textContent || el.getAttribute('aria-label'));
      if(full.length>48 || /semua\s*chat/i.test(full))continue;
      const m=full.match(/^chat\s*saya\s*[:(]?\s*(\d{1,4})\s*\)?$/i);
      if(m) return Number(m[1]);
    }
    return null;
  }
  function explicitlyEmpty() {
    // Bahasa Indonesia/Inggris yang lazim pada tampilan daftar tanpa chat.
    const check=document.querySelectorAll('[role="status"],[class*="empty" i],p,small,h3,h4');
    for(const el of Array.from(check).slice(0,300)) {
      if(!visible(el) || el.closest('#art-chatgacor-alert-root'))continue;
      const txt=normalize(el.textContent).toLowerCase();
      if(txt.length<90 && /^(?:tidak ada (?:chat|percakapan)|belum ada (?:chat|percakapan)|chat (?:saya )?kosong|no (?:chats|conversations)|no data|no results|belum ada pesan)$/.test(txt))return true;
    }
    return false;
  }
  function notification(name, type='incoming') {
    if (!('Notification' in window) || Notification.permission !== 'granted') return;
    if (document.visibilityState === 'visible') return;
    try {
      const title={incoming:'ChatGacor • Chat baru', messages:'ChatGacor • Pesan baru', tickets:'ChatGacor • Tiket baru', queue:'ChatGacor • Antrean baru'}[type]||'ChatGacor • Notifikasi';
      const n = new Notification(title, {
        body: `${name || 'Periksa Chat Saya'} • ${type === 'queue' ? 'pengunjung menunggu' : type === 'tickets' ? 'tiket perlu ditangani' : 'segera periksa dan balas'}.`,
        tag: 'art-chatgacor-'+type, renotify: true
      });
      n.onclick = () => { window.focus(); n.close(); };
    } catch { /* izin bisa dibatasi per browser */ }
  }

  function goodRoute() { return MATCH.test(location.pathname); }
  // Chat benar-benar sedang dilihat oleh agent: aktif, tab terlihat, dan jendela fokus.
  // Jangan diamkan alarm hanya karena chat terbuka di tab yang tidak sedang dibaca.
  function isChatViewed(id, row) {
    if (!id || document.visibilityState !== 'visible' || !document.hasFocus()) return false;
    const routeId = currentChatId();
    if (routeId && routeId === id) return true;
    // Cadangan untuk antarmuka SPA yang belum mengubah URL.
    const selected = row?.matches?.('[aria-selected="true"],[aria-current="page"],[data-state="active"]') ||
      !!row?.querySelector?.('a[aria-current="page"],a[aria-selected="true"],[role="listitem"][aria-selected="true"]');
    return !!selected;
  }
  function chatIdFromUrl(url) {
    if (!url) return '';
    try {
      const m = new URL(url, location.href).pathname.match(MATCH);
      return m && m[1] === APP_ID ? (m[2] || '') : '';
    } catch { return ''; }
  }
  function findParentRow(el) {
    let node = el;
    for (let i = 0; node && i < 5; i++, node=node.parentElement) {
      if (!visible(node) || node === document.body) continue;
      const b = node.getBoundingClientRect();
      if (b.height >= 37 && b.height <= 165 && b.width >= 120 && b.width <= 760) {
        const lower = (node.className && typeof node.className === 'string') ? node.className.toLowerCase() : '';
        if (node.matches('a,li,[role="listitem"],[data-chat-id],[data-conversation-id]') || /conversation|chat.?item|chat.?row|cursor-pointer/.test(lower)) return node;
      }
    }
    return el;
  }
  function collectRows() {
    const found = new Map();
    // 1. Tautan percakapan: cara terakurat untuk mengidentifikasi chat.
    for (const link of document.querySelectorAll('a[href*="my-chats/"]')) {
      const id = chatIdFromUrl(link.getAttribute('href'));
      if (!id || !visible(link) || link.closest('#art-chatgacor-alert-root')) continue;
      const row=findParentRow(link), rect=row.getBoundingClientRect();
      if(rect.height<30 || rect.height>220 || rect.width<90 || rect.width>860)continue;
      found.set(id, {id, el: row});
    }
    // 2. Aplikasi SPA dapat memakai div clickable tanpa <a>.
    const explicit = document.querySelectorAll('[data-chat-id],[data-conversation-id],[data-testid*="conversation" i],[data-testid*="chat-item" i],[class*="chat-item" i],[class*="chatItem"],[class*="conversation-item" i]');
    for (const el of explicit) {
      if (!visible(el) || el.closest('#art-chatgacor-alert-root')) continue;
      // Abaikan turunan item yang sudah masuk supaya tidak menghitung satu chat dua kali.
      const rect = el.getBoundingClientRect();
      if (rect.height < 37 || rect.height > 165 || rect.width < 130 || rect.width > 760) continue;
      let id = el.getAttribute('data-chat-id') || el.getAttribute('data-conversation-id') || '';
      id ||= chatIdFromUrl(el.querySelector('a[href*="my-chats/"]')?.getAttribute('href'));
      const txt = normalize(el.innerText || el.textContent).slice(0,220);
      if (!id && txt.length >= 4) {
        const firstLine = (el.innerText || el.textContent || '').split('\n').map(normalize).find(Boolean) || txt;
        id = 'row-' + hash(normKey(firstLine.slice(0,70)));
      }
      if (id && !found.has(id)) found.set(id, {id, el});
    }
    // 3. Cadangan untuk UI yang seluruh barisnya berupa div dengan cursor-pointer.
    if (!found.size) {
      // Hindari tombol navigasi umum; hanya kandidat baris daftar/chat yang bisa diklik.
      const options = document.querySelectorAll('[role="listitem"], [class~="cursor-pointer"]');
      let n = 0;
      for (const el of options) {
        if (++n > 750) break;
        if (!visible(el) || el.closest('#art-chatgacor-alert-root')) continue;
        const r = el.getBoundingClientRect();
        if (r.height < 55 || r.height > 138 || r.width < 190 || r.width > 650) continue;
        const value = normalize(el.innerText).slice(0,260);
        if (value.length < 6 || /^(chat saya|semua chat|pengaturan|daftar percakapan|profile|inbox|menu)$/i.test(value)) continue;
        const hasAvatar=!!el.querySelector('img,[class*="avatar" i]');
        const hasTiming=/\b(\d{1,2}:\d\d|hari ini|kemarin|yesterday|today|\d+\s*(?:min|mnt|minutes?|hours?|jam)\s*(?:ago|lalu)?)\b/i.test(value)
          || !!el.querySelector('time,[class*="timestamp" i]');
        if (!hasAvatar || !hasTiming) continue;
        const lines = (el.innerText || '').split('\n').map(normalize).filter(Boolean);
        const title = lines.find(s => s.length > 2 && !/^\d{1,2}:\d{2}$/.test(s)) || '';
        if (!title) continue;
        const id = chatIdFromUrl(el.querySelector('a[href*="my-chats/"]')?.getAttribute('href')) || 'row-' + hash(normKey(title));
        if (!found.has(id)) found.set(id, {id, el});
      }
    }
    return Array.from(found.values()).slice(0,180);
  }

  function numericUnread(el) {
    if (!visible(el)) return 0;
    const aria = [el.getAttribute('aria-label'), el.getAttribute('title'), el.getAttribute('data-testid')].filter(Boolean).join(' ');
    if (/unread|belum\s*dibaca|pesan\s*baru/i.test(aria)) {
      const match = aria.match(/\d+/);
      return match ? Math.min(99, Number(match[0])) : 1;
    }
    const cls = (typeof el.className === 'string') ? el.className : '';
    if (/(?:^|[\s_-])(unread|is-unread|not-read)(?:$|[\s_-])/i.test(cls)) {
      const num = normalize(el.textContent).match(/^\d{1,2}$/);
      return num ? Number(num[0]) : 1;
    }
    const val = normalize(el.textContent);
    if (!/^\d{1,2}$/.test(val) || el.children.length) return 0;
    const r = el.getBoundingClientRect();
    if (r.width > 42 || r.height > 34 || r.height < 9) return 0;
    const style = getComputedStyle(el);
    const bg = style.backgroundColor;
    if (!bg || /^(transparent|rgba\(0, 0, 0, 0\)|rgb\(255, 255, 255\))$/.test(bg)) return 0;
    const rgb = bg.match(/[\d.]+/g)?.map(Number) || [];
    if (rgb.length >= 3 && Math.max(...rgb.slice(0,3)) - Math.min(...rgb.slice(0,3)) < 16) return 0;
    return Math.min(99, Number(val));
  }
  function getUnread(row) {
    let n = 0;
    const nodes = [row, ...row.querySelectorAll('[aria-label],[title],[data-testid],span,small,[class*="unread" i]')];
    for (const el of nodes.slice(0,85)) n = Math.max(n, numericUnread(el));
    return n;
  }
  function extract(row) {
    const raw = (row.innerText || row.textContent || '').trim();
    const lines = raw.split('\n').map(normalize).filter(Boolean);
    const nameEl = row.querySelector('[data-testid*="name" i],[class*="font-semibold"],strong,h3,h4');
    const name = normalize(nameEl?.textContent || lines.find(v => v.length > 2 && !/^\d{1,2}:\d{2}$/.test(v)) || 'Member').slice(0,80);
    const previews = Array.from(row.querySelectorAll('[class*="truncate" i],[class*="line-clamp" i],[data-testid*="last-message" i]'))
      .map(el => normalize(el.textContent)).filter(Boolean);
    const textLine = lines.filter(v => v !== name && !/^\d{1,2}:\d{2}(?:\s*(am|pm))?$/i.test(v) && !/^\d{1,2}$/.test(v));
    const preview = normalize(previews.at(-1) || textLine.at(-1) || '').slice(0,450);
    const outgoing = /^(?:anda|you|saya|me|agent|cs)\s*[:：]/i.test(preview) || /^(?:sent|terkirim)\s*[:：]/i.test(preview);
    const key = hash(normKey(preview));
    return {name, preview, key, outgoing};
  }

  function sendAlarm(item, type='incoming', chatId='') {
    if (!state.enabled || !listScanned || scanRows===0 || (chatId && !latestList.includes(chatId))) return;
    if (ready) playIncomingTone(type);
    notification(item.name,type);
    const titles={incoming:'Chat baru masuk',messages:'Pesan baru',tickets:'Tiket baru',queue:'Ada antrean baru'};
    toast((titles[type]||'Notifikasi')+' • '+(item.name||'Chat Saya'));
  }
  function scan() {
    if(!goodRoute()) {
      if(scanRows || latestList.length){scanRows=0;latestList=[];listScanned=false;stopChatSounds();render();}
      return;
    }
    const rows=collectRows();
    const firstPass=!baselineEstablished;
    const nativeCount=nativeMyChatsCount();
    const emptyState=explicitlyEmpty();
    // SELALU hanya gunakan chat yang ada pada daftar saat ini.
    // State historis dari versi terdahulu tidak boleh membunyikan alarm.
    scanRows=rows.length;
    latestList=rows.map(x=>x.id);
    listScanned=true;
    if(!rows.length)emptyScans++;else emptyScans=0;
    const confirmedEmpty = rows.length===0 && (emptyState || nativeCount===0 || emptyScans>=2);
    const currentSet=new Set(latestList);
    let changed=false;
    for(const id of Object.keys(state.items)) {
      // Hapus cache chat yang sudah dikeluarkan/dipindah dari Chat Saya.
      if(!currentSet.has(id)) {delete state.items[id];changed=true;}
    }
    // Saat 0 chat, BUKAN sekadar menampilkan 0: putuskan sumber suara yang sedang aktif.
    if(!rows.length) {
      stopChatSounds();
      queuePendingWhileLocked=false;
    }
    // Jika ada badge angka resmi, gunakan ketika daftar tampil; jika tidak gunakan baris unik.
    // Jangan tahan angka lama ketika Chat Saya kosong.
    let listCount=rows.length;
    if(rows.length && nativeCount!==null && nativeCount>=rows.length) {
      listCount=nativeCount;
      queueCountSource='label';
    } else {
      queueCountSource='daftar';
    }
    updateQueueCount(listCount);
    lastScan=TIME();
    const events=[];
    for(const {id,el} of rows) {
      const d=extract(el),unread=getUnread(el);
      let item=state.items[id];
      if(!item) {
        item=state.items[id]={name:d.name,key:d.key,unread,pending:false,time:TIME()};
        if(unread>0 || (!firstPass && !!d.preview && !d.outgoing)) {
          item.pending=!isChatViewed(id,el);item.time=TIME();
          if(!firstPass) events.push({id,item,type:'incoming'});
        }
        changed=true;continue;
      }
      const changedPreview=!!d.preview && item.key!==d.key;
      const unreadIncreased=unread>0 && unread>(item.unread||0);
      const unreadCleared=item.pending && (item.unread||0)>0 && unread===0;
      const readInForeground=isChatViewed(id,el);
      const lastMsgByAgent=d.outgoing && changedPreview;
      const newMessage=unreadIncreased || (changedPreview && !d.outgoing && TIME()>=(item.suppressUntil||0));
      if(lastMsgByAgent || unreadCleared) {
        if(item.pending)changed=true;
        item.pending=false;item.suppressUntil=TIME()+500;
      } else if(newMessage) {
        item.pending=!readInForeground;
        item.time=TIME();changed=true;
        events.push({id,item,type:'messages'});
      } else if(readInForeground && item.pending) {
        item.pending=false;item.suppressUntil=TIME()+500;changed=true;
      }
      if(item.key!==d.key || item.unread!==unread || item.name!==d.name)changed=true;
      item.key=d.key;item.unread=unread;item.name=d.name;
    }
    // Setelah daftar pertama terbaca atau kosong terkonfirmasi, chat berikutnya
    // akan dianggap baru (juga apabila awalnya Chat Saya memang kosong).
    if(!baselineEstablished && (rows.length>0 || confirmedEmpty)) {
      baselineEstablished=true;state.firstScan=true;state.firstScanV5=true;changed=true;
    }
    if(changed)persist(true);
    // Jangan bunyikan suara untuk chat yang sekarang sudah tidak ada.
    if(events.length && scanRows>0) {
      const chosen=events.find(e=>e.type==='incoming')||events[0];
      if(currentSet.has(chosen.id))sendAlarm(chosen.item,chosen.type,chosen.id);
    }
    render();
  }
  function pendingCount() {
    // Menghitung HANYA ID yang sedang terlihat dalam Chat Saya, bukan isi cache lokal.
    if(!listScanned || scanRows===0)return 0;
    return latestList.reduce((n,id)=>n+(state.items[id]?.pending?1:0),0);
  }
  function scheduleScan(delay = 250) {
    if (scanTimer) return;
    scanTimer = setTimeout(() => { scanTimer = null; scan(); }, delay);
  }
  function markDone(id) {
    if (!id) return false;
    let item = state.items[id];
    if (!item) return false;
    item.pending = false;
    // Jangan menghidupkan alarm lama lagi sebelum ada pesan masuk baru.
    item.suppressUntil = TIME() + 500;
    item.time = TIME();
    persist(true);
    render();
    return true;
  }
  function markCurrentDone() {
    let id = currentChatId();
    if (!state.items[id]) {
      // Untuk UI yang memakai div tanpa tautan, gunakan item terakhir yang dipilih.
      const selected = document.querySelector('[aria-selected="true"][data-chat-id],[data-state="active"][data-chat-id],a[aria-current="page"][href*="my-chats/"]');
      id = selected?.getAttribute('data-chat-id') || chatIdFromUrl(selected?.getAttribute('href')) || id;
    }
    if (markDone(id)) toast('Pengingat chat ini dihentikan (sudah dibaca).');
    else toast('Buka percakapan terlebih dahulu.');
  }

  function composer(el) {
    if (!el || !(el instanceof Element)) return false;
    if (el.matches('textarea')) return !/search|cari|filter/i.test([el.placeholder,el.getAttribute('aria-label')].join(' '));
    if (el.matches('input')) return false;
    if (el.closest('[contenteditable="true"],[role="textbox"]')) {
      const c = el.closest('[contenteditable="true"],[role="textbox"]');
      return !/search|cari|filter/i.test([c.getAttribute('aria-label'),c.getAttribute('data-placeholder')].join(' '));
    }
    return false;
  }
  // Saat agen membuka/membaca chat, hentikan pengingat tanpa perlu membalas.
  // Ikuti route terbaru setelah click, bukan menganggap semua klik sebagai 'sudah baca'.
  function checkOpenedChatRead() {
    setTimeout(() => {
      if (!goodRoute() || document.visibilityState !== 'visible' || !document.hasFocus()) return;
      const id = currentChatId();
      if (id && state.items[id]?.pending) markDone(id);
      scheduleScan(80);
    }, 220);
  }
  // Saat balasan dikirim, pengingat juga dihentikan; tidak mengubah atau mengirim pesan.
  function replyDispatched() {
    const id = currentChatId();
    if (!id) return;
    // Begitu tombol Kirim / Enter dipakai, bunyi berhenti segera.
    markDone(id);
  }
  document.addEventListener('keydown', ev => {
    if (!goodRoute() || ev.key !== 'Enter' || ev.shiftKey || ev.altKey || ev.isComposing || !composer(ev.target)) return;
    const c = ev.target.closest('textarea,[contenteditable="true"],[role="textbox"]') || ev.target;
    const val = normalize(c.value || c.innerText || c.textContent);
    if (val) replyDispatched();
  }, true);
  document.addEventListener('click', ev => {
    if (!goodRoute() || host.contains(ev.target)) return;
    // Membuka percakapan di 'Chat Saya' dianggap sudah dibaca jika tab fokus.
    const clickedChat = ev.target.closest('a[href*="my-chats/"],[data-chat-id],[data-conversation-id]');
    if (clickedChat && (clickedChat.getAttribute('data-chat-id') || clickedChat.getAttribute('data-conversation-id') || chatIdFromUrl(clickedChat.getAttribute('href')))) {
      checkOpenedChatRead();
    }
    const btn = ev.target.closest('button,[role="button"]');
    if (!btn) return;
    const label = normalize([btn.getAttribute('aria-label'),btn.title,btn.getAttribute('data-testid'),btn.innerText].join(' '));
    const namedSend = /(?:^|\b)(?:send|kirim|balas|reply|paper-plane)(?:\b|$)/i.test(label) &&
      !/back|cancel|schedule|search|template|reaction|resend/i.test(label);
    // Cadangan: tombol kirim hanya berupa ikon, di kanan kolom pengetikan.
    const iconSend = !namedSend && !!btn.querySelector('svg') &&
      Array.from(document.querySelectorAll('textarea,[contenteditable="true"],[role="textbox"]'))
        .some(editor => {
          if (!visible(editor) || !composer(editor) || !normalize(editor.value || editor.innerText || editor.textContent)) return false;
          const a = editor.getBoundingClientRect(), b = btn.getBoundingClientRect();
          return b.left >= a.right - 44 && b.left <= a.right + 110 &&
            Math.abs((b.top+b.bottom)/2-(a.top+a.bottom)/2) <= 42;
        });
    if (namedSend || iconSend) replyDispatched();
  }, true);

  function render() {
    if (!ui.isConnected) return;
    syncReminderLoop();
    const count = pendingCount();
    const status = $('status');
    const detail = $('detail');
    const enable = $('enable');
    const led = $('led');
    $('count').textContent = String(count);
    $('queueCount').textContent = listScanned ? String(queueCountNow) : '—';
    $('queueBox').classList.toggle('high',queueCountNow>QUEUE_LIMIT);
    wrap.classList.toggle('alert', !!count && scanRows>0);
    wrap.classList.toggle('compact', state.compact);
    $('min').textContent = state.compact ? '+' : '−';
    $('rows').textContent = listScanned ? `${scanRows} baris terbaca${queueCountSource==='label'?' · label':''}` : 'Memeriksa daftar';
    if (!state.enabled) {
      status.textContent = 'Suara belum aktif';
      detail.textContent = count ? `${count} chat perlu ditangani` : 'Klik Aktifkan suara';
      enable.textContent = 'Aktifkan suara';
      led.className='led off';
    } else if (!ready) {
      status.textContent = 'Izinkan suara';
      detail.textContent = 'Klik tombol suara sekali';
      enable.textContent = 'Izinkan suara';
      led.className='led';
    } else {
      status.textContent = scanRows===0 && listScanned ? 'Tidak ada chat' : (count ? `${count} chat belum dibaca` : 'Siaga • Chat Saya');
      detail.textContent = scanRows===0 && listScanned ? '0 chat • alarm berhenti' : (count ? 'Buka/baca chat untuk hentikan' : 'Memantau pesan masuk');
      enable.textContent = 'Suara ON · Matikan';
      led.className='led on';
    }
    $('countdown').textContent = count ? 'Belum dibaca ↻' : (scanRows===0 ? 'Tidak ada alarm' : 'Siaga');
    $('audioStatus').textContent='Masuk: Incoming chat · Belum baca: chime · >15: queue';
  }

  $('enable').addEventListener('click', async () => {
    if (state.enabled && ready) {
      state.enabled = false;
      toast('Suara dimatikan. Pemantauan tetap berjalan.');
    } else {
      state.enabled = true;
      const ok = await unlockAudio();
      if (ok) {
        syncReminderLoop();flushQueueAudio();
        toast('Suara aktif • hanya chat yang masih ada di Chat Saya.');
      } else toast('Browser menolak audio. Cek izin suara tab Chrome.');
      if ('Notification' in window && Notification.permission === 'default') {
        // Permintaan izin notifikasi desktop hanya dipicu oleh klik pengguna.
        try { Notification.requestPermission(); } catch {}
      }
    }
    persist(true);
    render();
  });
  $('test').addEventListener('click', async () => {
    state.enabled = true;
    await unlockAudio();
    await playIncomingTone('incoming');
    setTimeout(() => testReminder(), 1900);
    setTimeout(() => playQueueSound(true), 3900);
    toast('Tes: Incoming chat → pengingat → antrean.');
    persist(true); render();
  });
  $('min').addEventListener('click', () => {
    state.compact = !state.compact; persist(true); render();
  });
  $('done').addEventListener('click', markCurrentDone);
  $('all').addEventListener('click', () => {
    for (const item of Object.values(state.items)) { item.pending = false; item.suppressUntil = TIME() + 500; }
    persist(true); render(); toast('Semua pengingat saat ini dihentikan.');
  });
  // Drag bubble tanpa mengklik tombol.
  (() => {
    let drag = null;
    $('drag').addEventListener('pointerdown', ev => {
      if (ev.target.closest('button')) return;
      ev.preventDefault();
      const rect=host.getBoundingClientRect();
      drag={x:ev.clientX,y:ev.clientY,l:rect.left,t:rect.top};
      $('drag').setPointerCapture?.(ev.pointerId);
    });
    $('drag').addEventListener('pointermove', ev => {
      if (!drag) return;
      const x=Math.max(2,Math.min(innerWidth-host.offsetWidth-2,drag.l+ev.clientX-drag.x));
      const y=Math.max(2,Math.min(innerHeight-host.offsetHeight-2,drag.t+ev.clientY-drag.y));
      host.style.left = x+'px';host.style.top = y+'px';host.style.right='auto';host.style.bottom='auto';
    });
    const end = () => {
      if (!drag) return;drag=null;
      state.pos={left:parseFloat(host.style.left),top:parseFloat(host.style.top)};persist(true);
    };
    $('drag').addEventListener('pointerup', end);
    $('drag').addEventListener('pointercancel', end);
  })();
  if (state.pos && Number.isFinite(state.pos.left) && Number.isFinite(state.pos.top)) {
    host.style.left=Math.min(Math.max(2,state.pos.left),innerWidth-100)+'px';
    host.style.top=Math.min(Math.max(2,state.pos.top),innerHeight-55)+'px';
    host.style.right='auto'; host.style.bottom='auto';
  }

  // Chrome menahan audio autoplay. Klik biasa pertama pada website dapat membuka AudioContext jika sebelumnya sudah diaktifkan.
  document.addEventListener('pointerdown', () => {
    if (state.enabled && !ready) unlockAudio();
  }, {capture:true, passive:true});

  const observer = new MutationObserver(mutations => {
    if (mutations.some(m => !host.contains(m.target))) scheduleScan(300);
  });
  function attachObserver() {
    if (!document.body) return;
    observer.observe(document.body, {childList:true,subtree:true,characterData:true,attributes:true,
      attributeFilter:['class','aria-label','aria-current','aria-selected','data-state','title']});
  }
  if (document.body) attachObserver();
  else document.addEventListener('DOMContentLoaded', attachObserver, {once:true});
  setInterval(scan, 2400); // cadangan saat halaman SPA mengubah data tanpa mutasi teramati
  setInterval(() => { if (goodRoute()) render(); }, 1500);
  window.addEventListener('focus', () => scheduleScan(100));
  document.addEventListener('visibilitychange', () => {if (!document.hidden) scheduleScan(100);});
  if (state.enabled) {
    toast('Klik sekali pada halaman agar Chrome mengizinkan suara.');
    unlockAudio().catch(() => {});
  }
  render();
  scheduleScan(300);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bootChatGacor, {once:true});
  else bootChatGacor();
})();
